import{_ as t,c as a,o as s,ae as n}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Questions fréquentes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1795170900000}'),r={name:"fr/guide/faq.md"};function o(i,e,u,l,m,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h1><p>Des réponses rapides sur Persim.</p><h3 id="persim-est-il-gratuit" tabindex="-1">Persim est-il gratuit ? <a class="header-anchor" href="#persim-est-il-gratuit" aria-label="Permalink to &quot;Persim est-il gratuit ?&quot;">​</a></h3><p>Les fonctions de navigation de base sont gratuites. Certaines fonctions avancées sont débloquées par un achat intégré ; la version gratuite affiche un petit badge dans la barre d&#39;onglets.</p><h3 id="quels-systemes-sont-compatibles" tabindex="-1">Quels systèmes sont compatibles ? <a class="header-anchor" href="#quels-systemes-sont-compatibles" aria-label="Permalink to &quot;Quels systèmes sont compatibles ?&quot;">​</a></h3><p>Persim est conçu pour macOS 12 ou supérieur, sur Apple Silicon et Intel.</p><h3 id="mes-donnees-sont-elles-envoyees" tabindex="-1">Mes données sont-elles envoyées ? <a class="header-anchor" href="#mes-donnees-sont-elles-envoyees" aria-label="Permalink to &quot;Mes données sont-elles envoyées ?&quot;">​</a></h3><p>Aucun compte n&#39;est nécessaire : historique, favoris, sessions et téléchargements restent sur votre Mac. Seules les fonctions qui nécessitent le réseau — comme la mise à jour d&#39;un abonnement — se connectent à Internet.</p><h3 id="comment-importer-les-favoris-d-un-autre-navigateur" tabindex="-1">Comment importer les favoris d&#39;un autre navigateur ? <a class="header-anchor" href="#comment-importer-les-favoris-d-un-autre-navigateur" aria-label="Permalink to &quot;Comment importer les favoris d&#39;un autre navigateur ?&quot;">​</a></h3><p>Exportez-les au format HTML depuis Chrome ou Edge, puis utilisez « Importer HTML » dans le gestionnaire de Persim. Dossiers et liens en double sont traités automatiquement.</p><h3 id="comment-enregistrer-une-video" tabindex="-1">Comment enregistrer une vidéo ? <a class="header-anchor" href="#comment-enregistrer-une-video" aria-label="Permalink to &quot;Comment enregistrer une vidéo ?&quot;">​</a></h3><p>Ouvrez le panneau médias, sélectionnez une vidéo détectée et téléchargez-la. Les fragments sont réunis en un MP4 que vous ouvrez avec votre application habituelle.</p><h3 id="comment-changer-de-langue" tabindex="-1">Comment changer de langue ? <a class="header-anchor" href="#comment-changer-de-langue" aria-label="Permalink to &quot;Comment changer de langue ?&quot;">​</a></h3><p>Ouvrez <code>persim://settings</code> → <strong>Général</strong> → <strong>Langue</strong>. 25 langues sont proposées ; rouvrez la fenêtre pour voir le changement.</p><h3 id="une-autre-question" tabindex="-1">Une autre question ? <a class="header-anchor" href="#une-autre-question" aria-label="Permalink to &quot;Une autre question ?&quot;">​</a></h3><p>Écrivez à <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> en expliquant ce que vous souhaitez faire.</p>',16)])])}const h=t(r,[["render",o]]);export{p as __pageData,h as default};
